#!/usr/bin/env python3
"""Record actual image viewing and independently verify each prepared file."""
import fcntl,importlib.util,io
from pathlib import Path
from PIL import Image
s=importlib.util.spec_from_file_location('b',Path(__file__).with_name('continuous-warsaw-batch-000090.py'));b=importlib.util.module_from_spec(s);s.loader.exec_module(b);h=b.h;i=b.i
lock=(b.R/'worker.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
observations={'498619': 'Complete wooden panel of the Seven Sleepers: seven seated young men in differently coloured tunics beneath Christ on a cloud, surrounded by an ornate gold border. All four outer board edges are visible; composition agrees with IK 375 description.', '498649': 'Complete board with Macarius standing on the right, monastery buildings on the left and a small face of Christ at upper left. Full brown and red borders remain visible. Matches IK 402; reverse inscriptions described by source were not viewed.', '498651': 'Complete surviving wooden panel with four standing saints beneath the face of Christ, worn silver background and visible metal braces on the lower and right borders. Entire physical perimeter is visible. Source title names Paraskeva but narrative allows Barbara; that ambiguity remains in original raw evidence. Native primary image 445172 is assigned directly to IK 404. Pixel ratio 315/380 differs from physical width/height 35.2/38.2 by about 10 percent. Actual image was individually viewed: four borders, edge damage, braces and all described figures remain visible, with no sign of a photographic crop. This establishes full supplied reproduction, not the correctness of source measurements. Preserve both dimensions and unaltered image proportions; no invented correction or unseen reverse claim.', '498509': 'Complete panel: Christ on an eight-ended cross, four standing saints, Adam skull below and patterned gold background/border. All four board edges remain visible; matches native IK 275. The separate existing Crucifixion at Golgotha IK 335 is a larger 49.5 x 44.3 cm physical object; not substituted.', '454465': 'Entire supplied rectangular painting: Virgin nursing the swaddled child, dark blue mantle, pink dress, radiating halo and black background with Cyrillic monograms. Native full-frame canvas dimensions and pixel proportions agree. IK 568 was formerly MP 3394 MNW; historical accession was globally checked. Source describes lined canvas and reports Radziwill provenance only according to seller; neither becomes an independently verified provenance or modern creation date.', '498392': 'Full wooden multi-scene icon with three upper scenes including the Tolga Virgin and Child centrally, and winged John the Baptist amid a row of saints below. Brown perimeter and all board edges visible. IK 170 matches source description. Counts as one physical panel, not separate scenes; related 1793 Rublev Museum painting is a narrative comparison, not this object date.', '498387': 'Full small wooden panel: Virgin with apostles left, kneeling Sergius and disciple right, Trinity medallion above and inscription below. All board edges and green border remain visible. Source gives IK 166 at 10.9 x 8.6 cm; other held apparition IK 162 is 22.8 x 18.2 cm and described with a different Sergius gesture. Distinct physical icon; source nineteenth-century date retained.'}
files=[];decisions=[]
for r in i.selected(b.B)['rows']:
 im=h.load(i.folder(b.B)/'prepared'/(r['artwork_id']+'.json'));assert im['state']=='prepared';raw=Path(im['path']).read_bytes();orig=Path(im['original_path']).read_bytes();assert h.sha(raw)==im['sha256'] and h.sha(orig)==im['source_sha256'] and len(raw)==im['bytes']<=100000
 with Image.open(io.BytesIO(raw)) as pic:pic.load();assert pic.format=='JPEG' and pic.size==(im['width'],im['height'])
 with Image.open(io.BytesIO(orig)) as pic:pic.load();assert abs(pic.width/pic.height-im['width']/im['height'])<.03
 assert '/Documents/' not in im['original_path']
 decisions.append(dict(artwork_id=r['artwork_id'],source_id=r['native_id'],artist=r['creator_label'],sha256=im['sha256'],decision='accept',viewed_individually=True,viewed_path=im['path'],tool='functions tools.view_image',observations=observations[r['native_id']],flag_resolution='Individual actual derivative viewed. The source_display_placeholder size heuristic flags the 315-pixel museum derivative, but the actual image is a complete authentic icon, not a placeholder. Full supplied frame, native inventory and source description match; no unseen reverse or tiny-inscription claim.',identity_confidence=.99,confidence_basis='Exact native object/image, inventory, dimensions, source description and observed physical composition; editorial judgment, not calibrated probability.'))
 files.append(dict(artwork_id=r['artwork_id'],sha256=im['sha256'],bytes=im['bytes'],complete_decode=True,proportions_preserved=True,original_sha256=im['source_sha256'],original_path=im['original_path']))
assert len(decisions)==7
review=dict(at=h.now(),batch_quality_decision='accept',reviewer='Codex actual image viewing',decisions=decisions,all_selected_files_individually_viewed=True,sample_only_files=[],limitations='Museum source images are 315 px wide. Compositions and complete supplied frames reviewed; no claim to inspect absent reverse views or tiny illegible inscriptions. Originals decoded and hashed; derivatives individually visually viewed.')
h.save(i.folder(b.B)/'visual-review.json',review);b.save('actual-visual-review.json',review);b.save('prewrite-file-verification.json',dict(at=h.now(),files=files,plan_sha256=h.pinned(b.PHASE)[1]))
print('7 actual per-image visual decisions and complete file checks saved')
